   "id": "M1:T4",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The system shall use SQL based database to store inventory information.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T5",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
