  {
   "id": "M1:T6",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "USB interface and divers are provided by Yoggie Corporation.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T7",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'design and implementation constraints' and asks about it."
