   "id": "M1:T12",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Shall install online help for users via the web interface",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T13",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T14",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Shall deliver Operations and Maintenance manual, Users Guide book, and Installation Instructions for the Administrator.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T15",
   "speaker": "Analyst",
   "act": "ask_topic",
