    }
   ]
  },
  {
   "id": "M1:T17",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Customers will be able to register, log in, and log out of their accounts.",
     "role": "statement"
    }
   ]
